*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 50%, #f093fb 100%);
  background-attachment: fixed;
  font-family: 'Segoe UI', sans-serif;
  color: #fff;
  display: flex;
  flex-direction: column;
}

/* Header */
.header {
  padding: 1.5rem 4rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.header__card {
  width: 100%;
  align-items: center;
  min-height: unset;
}

.header__greeting {
  font-size: 1.6rem;
  font-weight: 600;
}

.header__date {
  font-size: 1rem;
  opacity: 0.75;
}

.header__timer {
  font-family: 'Courier New', monospace;
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: 0.1em;
}

/* Main */
.main {
  flex: 1;
  padding: 2rem 4rem;
}

/* Card Grid */
.card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

/* Card */
.card {
  background: rgba(255, 255, 255, 0.45);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 16px;
  padding: 1.5rem;
  min-height: 180px;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  color: #1a1a1a;
}


.card__title {
  font-size: 1.1rem;
  font-weight: 600;
  padding-bottom: 0.5rem;
}

.card--center .card__title {
  text-align: center;
}

.card--span {
  min-height: unset;
  height: fit-content;
  align-self: start;
}

.card__body {
  font-size: 0.9rem;
  opacity: 0.75;
  flex: 1;
}

/* Theme toggle */
.theme-toggle {
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  font-size: 0.85rem;
  opacity: 0.75;
  padding: 0;
}

/* Dark mode */
body.dark {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
}

body.dark .card {
  background: rgba(0, 0, 0, 0.3);
  border-color: rgba(255, 255, 255, 0.15);
  color: #fff;
}

body.dark .todo-input {
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

body.dark .todo-form button {
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
}


/* Todo */
.todo-form {
  display: flex;
  gap: 0.5rem;
}

.todo-input {
  flex: 1;
  padding: 0.4rem 0.6rem;
  border-radius: 8px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  background: rgba(0, 0, 0, 0.05);
  color: #1a1a1a;
  font-size: 0.9rem;
  outline: none;
}

.todo-input::placeholder { opacity: 0.4; }

.todo-form button {
  padding: 0.4rem 0.8rem;
  border-radius: 8px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  background: #fff;
  color: #1a1a1a;
  cursor: pointer;
  font-size: 0.9rem;
}

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.todo-item span {
  flex: 1;
  font-size: 0.9rem;
}

.todo-item.done span {
  text-decoration: line-through;
  opacity: 0.5;
}

.todo-item button {
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  opacity: 0.5;
  font-size: 1rem;
  padding: 0;
}

.todo-item button:hover { opacity: 1; }

/* Focus Timer */
.focus-timer {
  font-family: 'Courier New', monospace;
  font-size: 3rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-align: center;
}

.focus-controls {
  display: flex;
  gap: 0.6rem;
  justify-content: center;
}

.focus-controls button {
  padding: 0.4rem 1rem;
  border-radius: 8px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  background: #fff;
  color: #1a1a1a;
  cursor: pointer;
  font-size: 0.9rem;
}

.focus-controls .btn-start {
  background: #6c63ff;
  border-color: #6c63ff;
  color: #fff;
}

body.dark .focus-controls button {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.3);
  color: #fff;
}

body.dark .focus-controls .btn-start {
  background: #6c63ff;
  border-color: #6c63ff;
}


/* Quick Links */
.link-form {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.link-input {
  flex: 1;
  min-width: 80px;
  padding: 0.4rem 0.6rem;
  border-radius: 8px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  background: rgba(0, 0, 0, 0.05);
  color: #1a1a1a;
  font-size: 0.85rem;
  outline: none;
}

.link-input::placeholder { opacity: 0.4; }

.link-form button {
  padding: 0.4rem 0.8rem;
  border-radius: 8px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  background: #fff;
  color: #1a1a1a;
  cursor: pointer;
  font-size: 0.85rem;
}

.link-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.link-item {
  display: flex;
  align-items: stretch;
  background: #fff;
  border: 1px solid rgba(0, 0, 0, 0.15);
  border-radius: 8px;
  overflow: hidden;
}

.link-item a {
  font-size: 0.85rem;
  color: #1a1a1a;
  text-decoration: none;
  padding: 0.35rem 0.7rem;
  display: block;
}

.link-item a:hover { background: rgba(0,0,0,0.05); }

.link-item button {
  background: none;
  border: none;
  border-left: 1px solid rgba(0, 0, 0, 0.1);
  color: #1a1a1a;
  cursor: pointer;
  opacity: 0.4;
  font-size: 0.75rem;
  padding: 0 0.5rem;
}

.link-item button:hover { opacity: 1; background: rgba(0,0,0,0.05); }

body.dark .link-input {
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

body.dark .link-form button {
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
}

body.dark .link-item {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.2);
}

body.dark .link-item a { color: #fff; }

body.dark .link-item button {
  border-left-color: rgba(255, 255, 255, 0.2);
  color: #fff;
}

